        var taskCompletionSource = new TaskCompletionSource<string?>();
        var layoutInflater = LayoutInflater.FromContext(Application.Context)!;
        var view = layoutInflater.Inflate(Resource.Layout.OtpDialog, null);

        var otpEditText = view!.FindViewById<EditText>(Resource.Id.dialog_input)!;

        var dialogBuilder = new AlertDialog.Builder(view.Context)
                .SetTitle("Enter OTP")
                .SetMessage("Please enter the OTP you received:")
                .SetView(view)
                .SetCancelable(false)
                .SetPositiveButton("OK", (_, _) =>
                {
                        var otp = otpEditText.Text;
                        taskCompletionSource.SetResult(otp);
                });
        var dialog = dialogBuilder.Create();

        dialog.Show();
        return await taskCompletionSource.Task;
}

