  const [IntervalFourthChart, setIntervalFourthChart] = useState("15m");

  const handleIntervalChange = useCallback((event: SelectChangeEvent<string>, chart: number) => {
    const value = event.target.value;

    switch (chart) {
    case 1:
      setIntervalFirstChart(value);
      break;
    case 2:
      setIntervalSecondChart(value);
      break;
    case 3:
      setIntervalThirdChart(value);
      break;
    case 4:
      setIntervalFourthChart(value);
      break;
    default:
      break;
