def init(self, identity, label, parents, children):
‘’‘
identity: int; its unique id in the graph
label: string;
parents: int->int dict; maps a parent node’s id to its multiplicity
children: int->int dict; maps a child node’s id to its multiplicity
‘’’
self.id = identity
self.label = label
self.parents = parents
self.children = children

def repr (self):
return "id: "+ str(self.id) + ", " + "label: " + str(self.label) + ", " + "parents: " + str(self.parents) + ", " + "children: " + str(self.children)
#ok

def get_id (self):
return self.id

def get_label (self):
return self.label
#ok

def get_parents_ids (self):
return [i for i in self.parents.keys()]
#ok

def get_children_ids (self):
return [i for i in self.children.keys()]
#ok

def get_children(self):
return self.children.values()

def get_parents(self):
return self.parents.values()

def set_id(self, i):
self.id = i
#ok

def set_label(self, i):
self.label = i
#ok

def set_parents_ids(self, i):
self.parents = i
#ok

def set_children_ids(self, i):
self.children = i
#ok

def add_child_id(self, i):
if i in self.get_children_ids():
self.children[i] +=1
else:
self.children[i] = 1
#ok

def add_parent_id(self, i):
if i in self.get_parents_ids():
self.parents[i] +=1
else:
self.parents[i] = 1
#ok

def remove_parent_once(self, id):
try:
if self.parents[id] <= 1:
self.remove_parent_id(id)
return
self.parents[id] = self.parents[id] - 1
except KeyError:
raise “Invalid parent id”
#ok

def remove_child_once(self, id):
try:
if self.children[id] <= 1:
self.remove_child_id(id)
return
self.children[id] = self.children[id] - 1
except KeyError:
raise “Invalid child id”
#ok

def remove_parent_id(self, id):
try:
self.parents.pop(id)
except KeyError:
raise “Invalid parent id”
#ok

def remove_child_id(self, id):
try:
self.children.pop(id)
except KeyError:
raise “Invalid child id”
#ok

def indegree(self):
res = 0
for p in self.parents.values():
res += p
return res

def outdegree(self):
res = 0
for c in self.children.values():
res +=c
return res

def degree(self):
return self.indegree()+self.outdegree()

